"""Deterministic structural audit; no scoring of society or automatic source approval."""
import collections,hashlib,json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[3]
HERE=pathlib.Path(__file__).resolve().parent
OUT=ROOT/'docs/data-readiness';OUT.mkdir(parents=True,exist_ok=True)
BLOCKS={1:'Tuotanto ja työ',2:'Toimeentulo ja jakautuminen',3:'Julkinen talous ja palvelut',4:'Väestö ja toimintakyky',5:'Varallisuus ja rakennettu ympäristö',6:'Ympäristö ja luonnonvarat',7:'Valta, demokratia ja oikeudet',8:'Kansalaisyhteiskunta, yhteisöt ja kulttuuri',9:'Turvallisuus ja yhteiskuntarauha'}
THEME_BLOCK={1:4,2:5,3:5,4:4,5:2,6:4,7:4,8:7,9:6,10:6,11:7,12:9,13:7,14:8,15:1,16:5,17:3,18:1,19:7,20:5,21:8,22:7,23:8,24:9,25:8,26:2,27:8,28:7,29:8,30:4,31:1,32:7}
RULES=[(9,r'crime|homicid|rikos|tuomitu|poliisi|vanki|rangaistus|turvallis|sotakuoll'),(6,r'energ|sähkö|päästö|puusto|metsätalousmaan|luonnonvara|fossiili|turve|vesivoima|tuulivoima|ydinvoima'),(7,r'äänest|voting|vaaliosall|demokra|oikeustur|korrupt'),(8,r'vapaaeht|yhdistys|järjestö|luottamus|trust|uskonn|\barvot\b|maailmankuva|redistribution_support'),(5,r'asumi|asunto|housing|varallis|wealth|nettovar|infrastruktu|rakennuskanta|ownership'),(2,r'tulonja|elinkustannu|cost_of_living|ostovoima|käytettävissä|disposable|gini|pienitulo|köyhyys|poverty|income|toimeentulo|velkaantumi|maksukyvy|ulosotto|häätö|pakkohuut'),(4,r'väest|vaesto|population|synty|fertility|elinajan|eodote|kuolleis|tervey|terveys|koulutu|education|tutkin|osaami|hoiva|care|toimintaky|lapset|lapsi|perhe|demograf|eläke|elakke'),(3,r'julkis|julkinen|verotu|veroras|valtiontal|valtionvel|budjet|fiscal|public_finance|edp|s13|s.13'),(1,r'työll|tyött|työvoim|työpan|työtun|työn|työmark|employment|unemployment|tuotan|tuotos|tuottavu|arvonlis|bkt|gdp|välituote|palkansaaja|teollis|elinkein|toimiala|kaupp|yritys|labour|labor')]
PERIODS=[('1850–1917',68,'p1_best'),('1918–1945',28,'p2_best'),('1946–1975',30,'p3_best'),('1976–1995',20,'p4_best'),('1996–2025',30,'p5_best')]
def primary(s):
 key=s.get('series_key','')
 if key.startswith(('fi.statfin15ab.','fi.statfin15ai.','fi.regional.statfin12bd_','fi.regional.hist_altp')):return 1,'source_dataset:production_or_employment_accounts'
 text=' '.join(str(s.get(k) or '') for k in ('title','theme','series_key')).lower()
 for b,pat in RULES:
  if re.search(pat,text):return b,'keyword:'+pat
 meta=s.get('metadata') or {};ids=meta.get('theme_ids') or s.get('linked_theme_ids') or []
 for i in ids:
  if str(i).isdigit() and int(i) in THEME_BLOCK:return THEME_BLOCK[int(i)],'theme:'+str(i)
 return None,'unresolved'
def classify(s):
 a=s.get('value_audit') or {};g=s.get('group_audit') or {}
 if not a.get('numeric_rows'):return 'E_no_numeric'
 if int(s.get('exact_cell_extra_rows') or 0)>0 or int(s.get('multirow_groupyears') or 0)>0:return 'D_cell_review'
 if not s.get('published') or not str(s.get('unit') or '').strip():return 'D_metadata_review'
 if g.get('dense_candidate_groups',0)>0 and s.get('frequency')=='annual':return 'A_curve_candidate'
 if a.get('candidate_rows',0)>0:return 'B_sparse_or_frequency_review'
 if a.get('estimate_rows',0)>0 or a.get('projection_rows',0)>0 or s.get('data_class')=='derived':return 'C_model_or_estimate_review'
 return 'D_provenance_review'
def build():
 raw=json.loads((HERE/('source-series-snapshot.json' if (HERE/'source-series-snapshot.json').exists() else 'compact-inputs.json')).read_text());support=json.loads((HERE/'support-snapshot.json').read_text());finance=json.loads((HERE/'source-finance-summary.json').read_text())
 rows=[];digests=collections.defaultdict(list)
 for s in raw:
  b,rule=primary(s);a=s.get('value_audit') or {};g=s.get('group_audit') or {};m=s.get('metadata') or {};serial=json.dumps(m,ensure_ascii=False).lower()
  flags=[]
  if a.get('missing_row_url_rows'):flags.append('row_url_missing')
  if a.get('missing_version_rows'):flags.append('source_version_incomplete')
  if a.get('missing_retrieved_rows'):flags.append('retrieval_time_incomplete')
  if a.get('null_numeric_rows'):flags.append('numeric_missing')
  if a.get('nonfinite_rows'):flags.append('nonfinite')
  if m.get('audit_comparability',bool(re.search('break|katkos|comparab|vertailukelp',serial))):flags.append('comparability_text_present_review_needed')
  if m.get('audit_overlap',bool(re.search('overlap|päällekk|nonoverlap|non.overlap|sisälty',serial))):flags.append('overlap_or_partition_note')
  if a.get('estimate_rows') or a.get('projection_rows'):flags.append('estimates_or_projections_present')
  if s.get('frequency')!='annual':flags.append('nonannual_frequency')
  national=s.get('geography') in ('Finland','Suomi') or (s.get('geography','').startswith('Nordics') and g.get('best_group_key')=='FI')
  if not national:flags.append('geography_or_national_group_review')
  rows.append(dict(series_key=s['series_key'],title=s['title'],block=b,mapping_rule=rule,readiness=classify(s),unit=s['unit'],geography=s['geography'],frequency=s['frequency'],group_count=g.get('group_count',0),best_group=s.get('best_group'),period_best_group_years={label:g.get(key,0) for label,n,key in PERIODS},value_audit=a,flags=flags,explicit_theme_ids=list(dict.fromkeys((m.get('theme_ids') or [])+(s.get('linked_theme_ids') or []))),eligible_for_composite=False))
  digests[(s['unit'],a.get('values_digest'))].append(s['series_key'])
 matches=[dict(unit=k[0],fingerprint=k[1],series_keys=v,interpretation='same stored cells, not proof of error; empty/suppressed/zero and sector aliases need review') for k,v in digests.items() if len(v)>1]
 summary={'audit_id':'calculation_readiness_20261026_v1','as_of':'2026-10-26','scope':'structural inventory; source labels not independently reverified; no causal approval; no composite weights','counts':support['datasets']['counts'][0], 'classes':dict(collections.Counter(x['readiness'] for x in rows)), 'unmapped_series':sum(x['block'] is None for x in rows),'null_numeric_rows':sum(x['value_audit'].get('null_numeric_rows',0) for x in rows),'exact_cell_extra_rows':sum(int(s['exact_cell_extra_rows']) for s in raw),'multirow_groupyears':sum(s['multirow_groupyears'] for s in raw),'duplicate_fingerprint_sets':len(matches),'duplicate_fingerprint_member_series':sum(len(x['series_keys']) for x in matches),'blocks':[], 'finance_totals':{k:sum(int(x[k] or 0) for x in finance) for k in ['series_count','empty_series','value_rows','checked_rows','imported_rows','review_rows','estimate_rows','other_rows','p1_dense','p2_dense','p3_dense','p4_dense','p5_dense']},'finance_source_groups':len(finance),'model_coverage':support['datasets']['model_computed'],'case_evidence':support['datasets']['case_summary'],'computed_uncertainty':support['datasets']['research_values'],'source_hashes':json.loads((HERE/'source-manifest.json').read_text())}
 for b,name in BLOCKS.items():
  rr=[r for r in rows if r['block']==b]
  summary['blocks'].append(dict(block=b,name=name,series=len(rr),classes=dict(collections.Counter(r['readiness'] for r in rr)),period_dense_series={label:sum(r['frequency']=='annual' and r['period_best_group_years'][label]>=n*.8 for r in rr) for label,n,k in PERIODS},examples=[r['series_key'] for r in sorted(rr,key=lambda x:(x['readiness']!='A_curve_candidate',-((x['best_group'] or {}).get('candidate_years',0)),x['series_key']))[:5]]))
 for name,obj in [('series-ledger.json',rows),('summary.json',summary),('overlap-candidates.json',matches),('finance-source-ledger.json',finance)]:
  (OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
 table=['| Lohko | Sarjoja | A: käyräehdokkaita | 1850–1917 | 1918–1945 | 1946–1975 | 1976–1995 | 1996–2025 |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for b in summary['blocks']:table.append('| '+b['name']+' | '+str(b['series'])+' | '+str(b['classes'].get('A_curve_candidate',0))+' | '+' | '.join(str(v) for v in b['period_dense_series'].values())+' |')
 lines=['# Nykyisen aineiston laskentakelpoisuus, 26.10.2026','','## Johtopäätös','','Aineisto riittää rajattujen mitattujen kehityskäyrien ja kolmen olemassa olevan hajotelmamallin hyödyntämiseen. Se ei vielä oikeuta yhdeksän lohkon yhteismitallista kokonaisindeksiä vuosille 1850–2050. Tämän kartoituksen A-luokka tarkoittaa rakenteellista käyräehdokasta, ei hyväksyttyä kansallista päämittaria tai syyvaikutusta. Yhtään sarjaa ei hyväksytä automaattisesti kokonaisindeksiin.','','## Laajuus ja rajaus','',f"Indikaattorirekisteri: {len(rows)} sarjaa, {summary['counts']['value_rows']} riviä ja {summary['counts']['series_groups']} sarja–ryhmä-yhdistelmää. Julkisen talouden erillisrekisteri: {summary['finance_totals']['series_count']} sarjamääritelmää ja {summary['finance_totals']['value_rows']} havaintoriviä; {summary['finance_totals']['empty_series']} määritelmällä ei ole havaintoja. Perheitä ei summata riippumattomaksi havaintomääräksi: sama alkuperäinen tieto voi esiintyä useassa paikassa.",'','Kartoitus perustuu nykyiseen tietokantaan. Se ei hae alkuperäislähteitä uudelleen eikä tarkista yksittäisten tilastolukujen oikeellisuutta. Sarjakatalogi luokiteltiin kokonaan; julkinen talous auditoitiin kaikkien sarjojen aggregaateista lähde-, yksikkö-, hinta-, valuutta- ja tilinpitokehysryhmittäin. Julkisen talouden yksittäisiä sarjoja ei rinnasteta indikaattorikatalogin A–E-luokkiin. Kyselyt ovat vain lukevia. Lähdepoiminnat tehtiin peräkkäin, eivät yhden tietokantatransaktion snapshotina.','','## Laskentakelpoisuuden luokat','',*['- '+k+': '+str(v)+' sarjaa.' for k,v in sorted(summary['classes'].items())],'','- A: julkaistu vuosisarja, yksikkö määritelty, vähintään yhdessä samassa ryhmässä vähintään 10 lähdemerkintöjen perusteella tarkistettua havaintovuotta ja vähintään 80 % ryhmän oman havaintovälin vuosista. Solutörmäys estää A-luokan.','- B: lähdemerkintöjen perusteella havaintoehdokkaita, mutta sarja on harva tai frekvenssi edellyttää erillistä käsittelyä.','- C: mallin, johdetun arvon, estimaatin tai ennusteen erillinen tarkistus.','- D: solujen, metatietojen tai provenienssin tarkistus ennen laskentaa.','- E: ei numeerista arvoa.','- Hyväksytty havaintoehdokas: observed, julkaistu, äärellinen numero, rivillä HTTP(S)-lähdeosoite ja validation_status joukosta source_verified, source_snapshot_checked, reviewed, validated, pdf_table_visually_checked, official_source_claim_checked. Nämä ovat aiempia tietokantamerkintöjä, eivät tämän auditoinnin uutta lähdevahvistusta.','- Kattavuuskynnys on tämän kartoituksen seulontasääntö, ei yleinen tilastollinen laatustandardi.','','## Yhdeksän lohkoa ja ajallinen kattavuus','','Lohkojako on alustava nimike- ja teemametatietoihin perustuva luokitus. Jokaisen sarjan sääntö näkyy ledgerissä. Se ei ole empiirinen klusterointi eikä painotus. Saman sarjan ensisijainen lohko on yksikäsitteinen, mutta se ei poista sarjojen keskinäisiä päällekkäisyyksiä.','','Jaksoluvut: sarjojen määrä, joilla vähintään yksi sama ryhmä kattaa vähintään 80 % koko jakson vuosista hyväksytyillä havaintoehdokkailla ja joiden frekvenssi on annual. Eri jaksoilla paras ryhmä voi vaihtua. Luvut eivät osoita yhtenäistä koko aikajanan sarjaa tai kansallista kattavuutta.','',*table,'',f"Luokittelematta jäi {summary['unmapped_series']} sarjaa; niitä ei pakotettu lohkoon.",'','## Päällekkäisyydet ja puuttuvuus','',f"Täsmälleen samalla sarja–ryhmä–vuosi–periodi-avaimella ylimääräisiä rivejä: {summary['exact_cell_extra_rows']}. Monirivisiä sarja–ryhmä–vuosi-soluja: {summary['multirow_groupyears']}. Numeerisesti tyhjiä soluja: {summary['null_numeric_rows']}; niitä ei käsitellä nollina.",f"Samoista yksiköistä ja samoista tallennetuista soluista löytyi {len(matches)} identtisen sormenjäljen ryhmää, joissa {summary['duplicate_fingerprint_member_series']} sarjaa. Tämä on tarkistuslista, ei virheluettelo: esimerkiksi nollasarjat, sektorien vastineet ja samat lähdearvot voivat olla aitoja. Eri ryhmäkoodit voivat myös peittää semanttisen päällekkäisyyden; sormenjälki ei löydä kaikkea.",'','Alue-, toimiala-, sektori-, ikä- ja sukupuolisarjoja sekä kokonaisuuksia ja niiden osia ei summata ilman määriteltyä ositusta. Koosteen aineistokattavuus erotetaan yhteiskunnan kehityspisteestä.','','## Valmiit laskentamallit','','| Malli | Perusvuosi | Laskettu jakso | Laskettuja pisteitä |','|---|---:|---|---:|']
 for x in summary['model_coverage']:lines.append(f"| {x['model_key']} | {x['baseline_year']} | {x['computed_first']}–{x['computed_last']} | {x['computed_points']} |")
 lines+=['','Pistemäärät sisältävät tekijä- ja ryhmäulottuvuuksia, eivät riippumattomia vuosihavaintoja. Tietokannassa on myös not_computable-rivejä koko aikajanalle: niitä ei saa tulkita lasketuiksi nolliksi. Mallit ovat eri yksiköissä, ja mallimetatiedot kieltävät mallien summan. Niiden laskentatarkistuksia ei ajettu tässä uudelleen.','','## Julkisen talouden erityistilanne','',f"Erillisrekisterissä {summary['finance_totals']['imported_rows']} observed-riviä on merkitty import_checked, {summary['finance_totals']['checked_rows']} observed-riviä source_verified ja {summary['finance_totals']['review_rows']} riviä needs_review. Statusmäärät ja value_kind-määrät ovat eri ulottuvuuksia eikä niitä summata keskenään.",'','Lähdevarmennettujen havaintojen 80 %:n jaksokynnystä ei ylitä yksikään yksittäinen julkisen talouden sarja tämän tiukan seulonnan mukaan. Tämä ei tarkoita aineiston puuttumista: runsas import_checked-aineisto tarvitsee lähdevarmennuksen sekä yhtenäisen sarjan muodostamisen tarkistuksen. Historialliset valuutat, käyvät ja kiinteät hinnat, yksikkökertoimet, ennakot, budjettiesitykset ja toteumat on erotettava. Lähderyhmäkohtainen ledger sisältää tarkat määrät.','','## Epävarmuus ja laadullinen näyttö','','Tutkimusrekisterin aktiivisissa johdetuissa arvoissa ei ole täytetty uncertainty_low/uncertainty_high-kenttiä. Tämä ei tarkoita arvojen olevan varmoja. Indikaattoririvien metatiedoista ei löytynyt tämän auditoinnin avainsanahaulla numeeriseen epävarmuuteen viittaavia merkintöjä; sarjatason dokumentaatiossa voi silti olla epävarmuustietoa. Menetelmä-, mittaus-, luokitus- ja kattavuusepävarmuudet pitää arvioida erikseen.','', 'Kaikki 419 mekanismitapausta ovat hypothesis-statuksella; yhdessäkään ei ole numeric_effect-lukua tai causal_effect_identified=true-merkintää. Ne palvelevat selityspolkuja eivätkä ole valmiita numeerisia vaikutuskertoimia. Teemojen kuusivaiheiset scores-kentät ovat toimituksellista jäsennystä, eivät mittaustuloksia.','', 'Simulaatiorekisterin 46 säädös–sarja-yhteyttä on merkitty scenario_assumption. Näistä 40 on merkitty include_in_composite=true. Tätä ei saa tulkita luvaksi käyttää niitä historiallisen kokonaisindeksin varmennettuina vaikutuksina. Nykyiset 12 normalisointisääntöä koskevat omaa pohjoismaista safe_corridor-kokonaisuutta, ja niiden lähtötasot ulottuvat 2025–2050 skenaarioina.','','## Suositeltu ensimmäinen laskentamittaristo','','1. Tuotanto: production_components ja sen samasta lähdevuosikerrasta sidotut panokset, 1975–2025. Säilytä hajotelman täsmäytys.','2. Toimeentulo: real_income_components, 1975–2025; erikseen ryhmäkohtaiset tulot ja tuloerot. Keskiarvo ei kuvaa kaikkia ryhmiä.','3. Väestö ja työ: age_structure, 1987–2024; elinajanodote ja väestörakenne erillisinä sarjoina.','4. Asuminen, ympäristö, kansalaisosallistuminen ja turvallisuus: valitse lohkolistan ehdokkaista yksittäiset tarkistetut kansalliset ryhmät. Historialliset rikostuomiot eivät ole suoraan tapahtuneen rikollisuuden mittari.','5. Julkinen talous: varmista ensin valitut kansantalouden tilinpidon sarjat, tilinpitokehys, sektorien ositus ja hinta-/valuuttamuunnokset.','6. Älä julkaise yhdeksän lohkon yhteispistettä ennen yhteisten vertailutasojen, painojen, riippuvuuksien ja epävarmuuden herkkyystarkastelua.','','## Priorisoidut jatkotoimet','','P0: hyväksyttyjen lähdestatusten ja lähteiden alkuperän tarkistus valitulle 15–25 päämittarille; perheiden välisen duplikaation tarkistus.','P0: nimetty kansallinen ryhmä ja vertailukelpoinen määritelmä jokaiselle päämittarille; alue-/toimialasarjojen pää- ja alaluokat.','P0: puuttuvan tiedon ja not_computable-arvojen julkaisusäännöt; ei automaattista interpolointia eikä nollakorvausta.','P1: julkisen talouden valittujen pitkien sarjojen lähde- ja hintaperustan varmennus; tietokannan source_verified-merkintä ei yksin ratkaise määritelmäkatkoksia.','P1: versionhallittu havaintoavain, yhteinen lähdetunniste ja korvausketju. Uusi lähde päivittää samaa havaintoa, ei lisää sen painoa.','P1: epävarmuusmalli, joka erottaa havaintovirheen, lähderiippuvuuden, menetelmävalinnat ja kattavuuden; ristiriita voi kasvattaa epävarmuutta.','P2: 1850–1974 harvojen havaintojen dokumentoidut historialliset vertailupisteet. Yhtenäinen akseli ei edellytä keksittyä vuosikäyrää.','P2: 2026–2050 erilliset skenaariot, joita ei käytetä historiallisten normalisointirajojen uudelleenmäärittelyyn.','','## Toistettavuus','','SQL-poiminnat ovat scripts/data/readiness-kansiossa. build-readiness.py muodostaa ledgerit ja raportin jäädytetyistä lähdepoiminnoista. compact-inputs.json säilyttää toistamiseen tarvittavat auditoidut sarjatiedot ilman laajoja lähdemetatietoja. Lähdepoimintojen SHA-256-tiivisteet ovat summary.json-tiedostossa. Luokittelu ei muuta lähdearvoja tai nykyisiä kuvaajia.']
 (OUT/'kartoitus.md').write_text('\n'.join(lines)+'\n')
 # Store only audit features used by this engine; original full snapshots stay local.
 compact=[]
 for s in raw:
  m=s.get('metadata') or {};txt=json.dumps(m,ensure_ascii=False).lower()
  keep={k:v for k,v in s.items() if k not in ('metadata','quality','description','source')}
  keep['metadata']={'theme_ids':m.get('theme_ids') or [],'audit_comparability':m.get('audit_comparability',bool(re.search('break|katkos|comparab|vertailukelp',txt))),'audit_overlap':m.get('audit_overlap',bool(re.search('overlap|päällekk|nonoverlap|non.overlap|sisälty',txt)))}
  compact.append(keep)
 (HERE/'compact-inputs.json').write_text(json.dumps(compact,ensure_ascii=False,separators=(',',':'))+'\n')
 print(json.dumps({k:v for k,v in summary.items() if k not in ('model_coverage','blocks','case_evidence','computed_uncertainty','source_hashes')},ensure_ascii=False,indent=2))
 return summary
if __name__=='__main__':build()
